<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Ubuntu-style Desktop</title>
<style>
  * { box-sizing: border-box; }
  html, body { margin:0; padding:0; height:100%; width:100%; }
  body { font-family: 'Ubuntu', 'Segoe UI', Arial, sans-serif; overflow:hidden; }

  #desktop {
    position:relative;
    width:100vw;
    height:100vh;
    overflow:hidden;
    background:
      radial-gradient(circle at 80% 20%, rgba(233,84,32,0.35), transparent 45%),
      linear-gradient(160deg, #2c001e 0%, #4b1a3a 35%, #3a1130 60%, #1c1c1c 100%);
  }

  /* Top bar */
  #topbar {
    position:absolute; top:0; left:0; right:0; height:28px;
    background:rgba(20,20,20,0.75);
    color:#eee;
    display:flex; align-items:center; justify-content:center;
    font-size:13px;
    letter-spacing:.5px;
    z-index:5000;
    user-select:none;
  }

  /* Windows */
  .window {
    position:absolute;
    display:none;
    flex-direction:column;
    width:480px;
    height:360px;
    min-width:360px;
    min-height:240px;
    background:#2d2d2d;
    border-radius:8px;
    overflow:hidden;
    box-shadow:0 15px 40px rgba(0,0,0,0.55);
    z-index:100;
  }
  .titlebar {
    background:#3b3b3b;
    padding:8px 10px;
    display:flex;
    align-items:center;
    justify-content:space-between;
    cursor:move;
    color:#f0f0f0;
    font-size:14px;
    font-weight:600;
    user-select:none;
  }
  .win-close {
    background:#e95420;
    border:none;
    color:#fff;
    width:22px;
    height:22px;
    border-radius:50%;
    cursor:pointer;
    font-size:13px;
    line-height:1;
    display:flex;
    align-items:center;
    justify-content:center;
  }
  .win-close:hover { background:#ff6a34; }

  /* Files app */
  .toolbar {
    display:flex;
    align-items:center;
    gap:10px;
    padding:6px 10px;
    background:#262626;
    color:#ddd;
    font-size:13px;
  }
  #files-up {
    background:#4a4a4a;
    color:#fff;
    border:none;
    padding:5px 12px;
    border-radius:4px;
    cursor:pointer;
    font-size:13px;
  }
  #files-up:hover { background:#5a5a5a; }
  #files-path {
    font-family: monospace;
    color:#9fdcff;
  }
  .listing {
    flex:1;
    overflow:auto;
    padding:14px;
    display:flex;
    flex-wrap:wrap;
    align-content:flex-start;
    gap:16px;
    background:#1e1e1e;
  }
  .fs-item {
    display:flex;
    flex-direction:column;
    align-items:center;
    width:82px;
    color:#eee;
    font-size:12px;
    cursor:default;
    padding:8px 4px;
    border-radius:6px;
    user-select:none;
    text-align:center;
    word-break:break-word;
  }
  .fs-item:hover { background:rgba(255,255,255,0.09); }
  .fs-item.folder::before {
    content:'📁';
    font-size:30px;
    display:block;
    margin-bottom:4px;
  }
  .fs-item.file::before {
    content:'📄';
    font-size:30px;
    display:block;
    margin-bottom:4px;
  }

  /* Notepad app */
  #tabs {
    display:flex;
    background:#262626;
    align-items:center;
    padding:5px 6px;
    gap:5px;
    overflow-x:auto;
  }
  .tab {
    background:#3b3b3b;
    color:#ddd;
    padding:6px 10px;
    border-radius:5px 5px 0 0;
    cursor:pointer;
    font-size:13px;
    display:flex;
    align-items:center;
    gap:8px;
    white-space:nowrap;
    max-width:160px;
  }
  .tab-name {
    overflow:hidden;
    text-overflow:ellipsis;
    white-space:nowrap;
  }
  .tab.active { background:#1e1e1e; color:#fff; font-weight:600; }
  .tab-close {
    opacity:.55;
    font-size:12px;
    line-height:1;
  }
  .tab-close:hover { opacity:1; }
  #new-tab {
    background:#4a4a4a;
    color:#fff;
    border:none;
    width:26px;
    height:26px;
    border-radius:5px;
    cursor:pointer;
    font-size:16px;
    flex-shrink:0;
  }
  #new-tab:hover { background:#5a5a5a; }

  #editor {
    flex:1;
    background:#1e1e1e;
    color:#e8e8e8;
    border:none;
    outline:none;
    padding:14px;
    font-family: 'Courier New', monospace;
    font-size:14px;
    resize:none;
    line-height:1.5;
  }

  /* Taskbar / dock */
  #taskbar {
    position:absolute;
    bottom:14px;
    left:50%;
    transform:translateX(-50%);
    display:flex;
    gap:16px;
    background:rgba(25,25,25,0.65);
    backdrop-filter: blur(6px);
    padding:10px 18px;
    border-radius:18px;
    box-shadow:0 8px 24px rgba(0,0,0,0.45);
    z-index:1000;
  }
  #taskbar button {
    width:54px;
    height:54px;
    border-radius:13px;
    border:none;
    background:#3b3b3b;
    color:#fff;
    font-size:10px;
    cursor:pointer;
    display:flex;
    flex-direction:column;
    align-items:center;
    justify-content:center;
    gap:3px;
    transition: transform .15s ease, background .15s ease;
  }
  #taskbar button::before { font-size:22px; }
  #open-files::before { content:'🗂️'; }
  #open-notepad::before { content:'📝'; }
  #taskbar button:hover { transform:translateY(-8px); background:#4d4d4d; }
</style>
</head>
<body>

<div id="desktop">
  <div id="topbar"><span id="clock"></span></div>

  <!-- Files window -->
  <div id="files-window" class="window" style="left:70px; top:60px;">
    <div class="titlebar">
      <span>Files</span>
      <button class="win-close" title="Close">✕</button>
    </div>
    <div class="toolbar">
      <button id="files-up">⬆ Up</button>
      <span id="files-path">/</span>
    </div>
    <div id="files-listing" class="listing"></div>
  </div>

  <!-- Notepad window -->
  <div id="notepad-window" class="window" style="left:430px; top:110px;">
    <div class="titlebar">
      <span>Notepad</span>
      <button class="win-close" title="Close">✕</button>
    </div>
    <div id="tabs">
      <button id="new-tab" title="New tab">+</button>
    </div>
    <textarea id="editor" spellcheck="false"></textarea>
  </div>

  <div id="taskbar">
    <button id="open-files">Files</button>
    <button id="open-notepad">Notepad</button>
  </div>
</div>

<script>
(function(){
  "use strict";

  /* ---------- Clock ---------- */
  const clockEl = document.getElementById('clock');
  function tick(){
    const d = new Date();
    let h = d.getHours().toString().padStart(2,'0');
    let m = d.getMinutes().toString().padStart(2,'0');
    const days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
    clockEl.textContent = days[d.getDay()] + ' ' + h + ':' + m;
  }
  tick();
  setInterval(tick, 1000*10);

  /* ---------- Window management ---------- */
  const desktop = document.getElementById('desktop');
  let zTop = 100;

  function bringToFront(win){
    zTop += 1;
    win.style.zIndex = zTop;
  }

  function openWindow(win){
    win.style.display = 'flex';
    bringToFront(win);
  }

  function makeDraggable(win){
    const titlebar = win.querySelector('.titlebar');
    let dragging = false;
    let offsetX = 0, offsetY = 0;

    titlebar.addEventListener('mousedown', (e) => {
      if (e.target.classList.contains('win-close')) return;
      dragging = true;
      bringToFront(win);
      const rect = win.getBoundingClientRect();
      const deskRect = desktop.getBoundingClientRect();
      offsetX = e.clientX - rect.left;
      offsetY = e.clientY - rect.top;
      e.preventDefault();
    });

    document.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      const deskRect = desktop.getBoundingClientRect();
      let x = e.clientX - deskRect.left - offsetX;
      let y = e.clientY - deskRect.top - offsetY;
      x = Math.max(0, Math.min(x, deskRect.width - 100));
      y = Math.max(0, Math.min(y, deskRect.height - 40));
      win.style.left = x + 'px';
      win.style.top = y + 'px';
    });

    document.addEventListener('mouseup', () => { dragging = false; });

    win.addEventListener('mousedown', () => bringToFront(win));
  }

  document.querySelectorAll('.window').forEach(makeDraggable);

  document.querySelectorAll('.win-close').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const win = e.target.closest('.window');
      win.style.display = 'none';
    });
  });

  const filesWindow = document.getElementById('files-window');
  const notepadWindow = document.getElementById('notepad-window');

  document.getElementById('open-files').addEventListener('click', () => openWindow(filesWindow));
  document.getElementById('open-notepad').addEventListener('click', () => openWindow(notepadWindow));

  /* ---------- Files app (fake filesystem) ---------- */
  const fsRoot = {
    type: 'folder',
    children: {
      bin: { type:'folder', children:{
        bash: {type:'file'}, ls: {type:'file'}, cat: {type:'file'}, mv: {type:'file'}
      }},
      etc: { type:'folder', children:{
        'passwd': {type:'file'}, 'hosts': {type:'file'}, 'fstab': {type:'file'},
        'ssh': { type:'folder', children:{ 'sshd_config': {type:'file'} } }
      }},
      home: { type:'folder', children:{
        user: { type:'folder', children:{
          Documents: { type:'folder', children:{
            'resume.odt': {type:'file'}, 'todo.txt': {type:'file'}
          }},
          Downloads: { type:'folder', children:{
            'installer.deb': {type:'file'}
          }},
          Pictures: { type:'folder', children:{
            'wallpaper.png': {type:'file'}, 'vacation.jpg': {type:'file'}
          }},
          '.bashrc': {type:'file'},
          '.profile': {type:'file'}
        }}
      }},
      usr: { type:'folder', children:{
        bin: { type:'folder', children:{ python3:{type:'file'}, gcc:{type:'file'} } },
        lib: { type:'folder', children:{} },
        share: { type:'folder', children:{} }
      }},
      var: { type:'folder', children:{
        log: { type:'folder', children:{ 'syslog':{type:'file'}, 'auth.log':{type:'file'} } },
        www: { type:'folder', children:{} }
      }}
    }
  };

  let currentPath = [];

  function getNode(path){
    let node = fsRoot;
    for (const part of path){
      if (!node.children || !node.children[part]) return null;
      node = node.children[part];
    }
    return node;
  }

  function renderFiles(){
    const node = getNode(currentPath);
    document.getElementById('files-path').textContent = '/' + currentPath.join('/');
    const listing = document.getElementById('files-listing');
    listing.innerHTML = '';

    const names = Object.keys(node.children).sort((a,b) => {
      const an = node.children[a], bn = node.children[b];
      if (an.type !== bn.type) return an.type === 'folder' ? -1 : 1;
      return a.localeCompare(b);
    });

    for (const name of names){
      const entry = node.children[name];
      const div = document.createElement('div');
      div.className = 'fs-item ' + entry.type;
      div.textContent = name;
      div.addEventListener('dblclick', () => {
        if (entry.type === 'folder'){
          currentPath.push(name);
          renderFiles();
        }
      });
      listing.appendChild(div);
    }
  }

  document.getElementById('files-up').addEventListener('click', () => {
    if (currentPath.length > 0){
      currentPath.pop();
      renderFiles();
    }
  });

  renderFiles();

  /* ---------- Notepad app ---------- */
  const TABS_KEY = 'desktop-notepad-tabs-v1';
  const ACTIVE_KEY = 'desktop-notepad-active-v1';

  let tabs = [];
  let activeId = null;

  function loadState(){
    try {
      const raw = localStorage.getItem(TABS_KEY);
      if (raw){
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed) && parsed.length > 0){
          tabs = parsed;
        }
      }
    } catch(e){ tabs = []; }

    if (tabs.length === 0){
      tabs = [{ id: 'tab-' + Date.now(), name: 'Untitled 1', content: '' }];
    }

    const savedActive = localStorage.getItem(ACTIVE_KEY);
    if (savedActive && tabs.some(t => t.id === savedActive)){
      activeId = savedActive;
    } else {
      activeId = tabs[0].id;
    }
  }

  function saveState(){
    localStorage.setItem(TABS_KEY, JSON.stringify(tabs));
    localStorage.setItem(ACTIVE_KEY, activeId);
  }

  let tabCounter = tabs.length;

  function renderTabs(){
    const tabsBar = document.getElementById('tabs');
    // remove existing .tab elements (keep #new-tab button)
    tabsBar.querySelectorAll('.tab').forEach(el => el.remove());
    const newTabBtn = document.getElementById('new-tab');

    tabs.forEach(t => {
      const tabEl = document.createElement('div');
      tabEl.className = 'tab' + (t.id === activeId ? ' active' : '');
      tabEl.dataset.id = t.id;

      const nameSpan = document.createElement('span');
      nameSpan.className = 'tab-name';
      nameSpan.textContent = t.name;
      tabEl.appendChild(nameSpan);

      const closeSpan = document.createElement('span');
      closeSpan.className = 'tab-close';
      closeSpan.textContent = '✕';
      closeSpan.addEventListener('click', (e) => {
        e.stopPropagation();
        closeTab(t.id);
      });
      tabEl.appendChild(closeSpan);

      tabEl.addEventListener('click', () => {
        activeId = t.id;
        saveState();
        renderTabs();
        renderEditor();
      });

      tabsBar.insertBefore(tabEl, newTabBtn);
    });
  }

  function renderEditor(){
    const editor = document.getElementById('editor');
    const t = tabs.find(t => t.id === activeId);
    editor.value = t ? t.content : '';
  }

  function closeTab(id){
    const idx = tabs.findIndex(t => t.id === id);
    if (idx === -1) return;
    tabs.splice(idx, 1);
    if (tabs.length === 0){
      tabCounter += 1;
      tabs.push({ id: 'tab-' + Date.now(), name: 'Untitled ' + tabCounter, content: '' });
    }
    if (activeId === id){
      const newIdx = Math.max(0, idx - 1);
      activeId = tabs[newIdx].id;
    }
    saveState();
    renderTabs();
    renderEditor();
  }

  document.getElementById('new-tab').addEventListener('click', () => {
    tabCounter += 1;
    const t = { id: 'tab-' + Date.now() + '-' + tabCounter, name: 'Untitled ' + tabCounter, content: '' };
    tabs.push(t);
    activeId = t.id;
    saveState();
    renderTabs();
    renderEditor();
  });

  document.getElementById('editor').addEventListener('input', (e) => {
    const t = tabs.find(t => t.id === activeId);
    if (t){
      t.content = e.target.value;
      saveState();
    }
  });

  loadState();
  renderTabs();
  renderEditor();

})();
</script>
</body>
</html>
